fn shape_for(c: char) -> Option<&'static Shape> {
    SHAPES.iter().find(|s| s.base == c)
}

fn is_mark(c: char) -> bool {
    matches!(c as u32, 0x064B..=0x065F | 0x0670 | 0x08D3..=0x08FF)
}

fn joins_previous(c: char) -> bool {
    if c == '\u{0640}' { return true; }
    shape_for(c).is_some_and(|s| s.final_form != '\0' || s.medial != '\0')
}

fn joins_next(c: char) -> bool {
    if c == '\u{0640}' { return true; }
    shape_for(c).is_some_and(|s| s.initial != '\0' || s.medial != '\0')
}

fn previous_base(chars: &[char], mut i: usize) -> Option<char> {
    while i > 0 {
        i -= 1;
        let c = chars[i];
        if is_mark(c) { continue; }
        return Some(c);
    }
    None
}

fn next_base(chars: &[char], mut i: usize) -> Option<char> {
    while i < chars.len() {
        let c = chars[i];
        i += 1;
        if is_mark(c) { continue; }
        return Some(c);
    }
    None
}

fn shape_logical(input: &str, out: &mut [char; MAX_TEXT]) -> usize {
    let mut n = 0;
    for c in input.chars().take(MAX_TEXT) {
        // This compact bitmap renderer has no mark-positioning engine. Drop optional tashkeel
        // rather than drawing the font's dotted-circle fallback glyph beside the letter.
        if is_mark(c) { continue; }
        out[n] = c;
        n += 1;
    }
    let original = *out;
    for i in 0..n {
        let c = original[i];
        // Tatweel already has the correct joining appearance and must not be converted to a form.
        if c == '\u{0640}' { continue; }
        let Some(form) = shape_for(c) else { continue; };
        let prev = previous_base(&original[..n], i).is_some_and(|p| joins_next(p) && joins_previous(c));
        let next = next_base(&original[..n], i + 1).is_some_and(|q| joins_next(c) && joins_previous(q));
        out[i] = if prev && next && form.medial != '\0' {
            form.medial
        } else if prev && form.final_form != '\0' {
            form.final_form
        } else if next && form.initial != '\0' {
            form.initial
        } else {
            form.isolated
        };
    }
    n
}

pub fn contains_rtl(input: &str) -> bool {
    input.chars().any(is_rtl)
}

fn is_rtl(c: char) -> bool {
    matches!(c as u32, 0x0600..=0x08FF | 0xFE70..=0xFEFF)
}

fn is_ltr(c: char) -> bool {
    c.is_ascii_alphanumeric() || matches!(c as u32, 0x0660..=0x0669 | 0x06F0..=0x06F9)
}

fn direction(c: char) -> u8 {
    // Digits live in the Arabic Unicode block too, but remain left-to-right sequences.
    if is_ltr(c) { 2 } else if is_rtl(c) { 1 } else { 0 }
}

fn mirror(c: char) -> char {
    match c {
        '(' => ')', ')' => '(', '[' => ']', ']' => '[', '{' => '}', '}' => '{',
        '<' => '>', '>' => '<',
        _ => c,
    }
}

/// Produces glyphs in left-to-right paint order after contextual Arabic shaping and a compact bidi pass.
/// It supports common Arabic / Latin / digit / punctuation combinations; optional vowel marks are omitted.
pub fn visual(input: &str, out: &mut [char; MAX_TEXT]) -> usize {
    let mut shaped = ['\0'; MAX_TEXT];
    let n = shape_logical(input, &mut shaped);
    if n == 0 { return 0; }

    // Each remaining codepoint is one display unit; optional vowel marks were removed above.
    let mut starts = [0u8; MAX_TEXT];
    let lens = [1u8; MAX_TEXT];
    let mut dirs = [0u8; MAX_TEXT];
    let count = n;
    for i in 0..n {
        starts[i] = i as u8;
        dirs[i] = direction(shaped[i]);
    }

    let base_dir = (0..count).find_map(|i| if dirs[i] != 0 { Some(dirs[i]) } else { None }).unwrap_or(2);
    let mut prior = 0u8;
    for i in 0..count {
        if dirs[i] == 0 {
            dirs[i] = if prior != 0 { prior } else { base_dir };
        } else {
            prior = dirs[i];
        }
    }

    let mut run_start = [0u8; MAX_TEXT];
    let mut run_end = [0u8; MAX_TEXT];
    let mut run_dir = [0u8; MAX_TEXT];
    let mut runs = 0usize;
    let mut at = 0usize;
    while at < count {
        let d = dirs[at];
        let start = at;
        at += 1;
        while at < count && dirs[at] == d { at += 1; }
        run_start[runs] = start as u8;
        run_end[runs] = at as u8;
        run_dir[runs] = d;
        runs += 1;
    }

    let mut written = 0usize;
    let mut emit_cluster = |cluster: usize, rtl: bool, out: &mut [char; MAX_TEXT], written: &mut usize| {
        let start = starts[cluster] as usize;
        for j in 0..lens[cluster] as usize {
            if *written >= MAX_TEXT { return; }
            let mut c = shaped[start + j];
            if rtl { c = mirror(c); }
            out[*written] = c;
            *written += 1;
        }
    };

    if base_dir == 1 {
        for r in (0..runs).rev() {
            let start = run_start[r] as usize;
            let end = run_end[r] as usize;
            if run_dir[r] == 1 {
                for c in (start..end).rev() { emit_cluster(c, true, out, &mut written); }
            } else {
                for c in start..end { emit_cluster(c, false, out, &mut written); }
            }
        }
    } else {
        for r in 0..runs {
            let start = run_start[r] as usize;
            let end = run_end[r] as usize;
            if run_dir[r] == 1 {
                for c in (start..end).rev() { emit_cluster(c, true, out, &mut written); }
            } else {
                for c in start..end { emit_cluster(c, false, out, &mut written); }
            }
        }
    }
    written
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn arabic_letters_get_contextual_presentation_forms() {
        let mut out = ['\0'; MAX_TEXT];
        let n = visual("سلام", &mut out);
        let rendered: String = out[..n].iter().collect();
        assert!(rendered.chars().all(|c| (0xFE70..=0xFEFF).contains(&(c as u32))), "{rendered}");
        assert_eq!(n, 4);
    }

    #[test]
    fn latin_runs_and_digits_stay_in_order_inside_rtl_text() {
        let mut out = ['\0'; MAX_TEXT];
        let n = visual("مرحبا ABC 123", &mut out);
        let rendered: String = out[..n].iter().collect();
        assert!(rendered.contains("ABC"), "{rendered}");
        assert!(rendered.contains("123"), "{rendered}");
        let n = visual("مرحبا ١٢٣", &mut out);
        let rendered: String = out[..n].iter().collect();
        assert!(rendered.contains("١٢٣"), "Arabic digits reversed: {rendered}");
    }

    #[test]
    fn empty_and_english_text_are_unchanged() {
        let mut out = ['\0'; MAX_TEXT];
        assert_eq!(visual("", &mut out), 0);
        let n = visual("Hello 123", &mut out);
        assert_eq!(out[..n].iter().collect::<String>(), "Hello 123");
    }
}
